function cardMarkup(c,{action='detail',extra='',classes='',idx='',label=''}={}){const e=elementMap[c.element];return `<button class="game-card rarity-${c.rarity} ${classes}" data-action="${action}" data-id="${c.id}" ${idx!==''?`data-index="${idx}"`:''} style="--card-border:${typeColors[c.type]};--element-color:${e.color}" aria-label="${esc(label||`${c.name}、${TYPE_LABELS[c.type]}、${c.type==='fusion'?'特殊デッキ':`コスト${c.cost}`}、詳細を表示`)}">${art(c)}<div class="card-top"><span class="cost-gem ${c.type==='fusion'?'fusion-gem':''}">${c.type==='fusion'?'合':c.cost}</span><span class="element-badge" title="${e.name}">${e.glyph}</span></div><div class="card-bottom"><div class="card-kind"><span>${TYPE_LABELS[c.type]} · ${e.name}</span><span class="rarity" title="${esc(RARITY_LABELS[c.rarity])}">${esc(RARITY_LABELS[c.rarity])}</span></div><div class="card-name">${esc(c.name)}</div><p class="card-effect">${esc(c.text)}</p><div class="card-stats">${['beast','fusion'].includes(c.type)?`<span title="攻撃力">${icon('sword')}${c.attack}</span><em class="card-model">${MODEL_LABELS[c.model]||''}</em><span class="health" title="守備力">${icon('shield')}${c.hp}</span>`:`<span class="card-subtype-stat">${icon(c.type==='miracle'?'spark':'trap')} ${esc(SUBTYPE_LABELS[c.subtype]||TYPE_LABELS[c.type])}</span>`}</div></div>${extra}</button>`;}
